(function () {
  const playlist = [
    "/files/bgm/finale.mp3",
    "/files/bgm/until_sunfall.mp3",
    "/files/bgm/献给如今正迈步前行的你.mp3"
  ];
  const shuffle = true;   // true = 随机播放；false = 列表顺序循环

  const audio = document.getElementById("bgm");
  const order = playlist.map((_, i) => i);
  let cursor = 0;

  function shuffleArray(a) {            // Fisher-Yates 洗牌
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
  }

  function load() { audio.src = playlist[order[cursor]]; }

  audio.addEventListener("ended", function () {
    cursor++;
    if (cursor >= order.length) {        
      cursor = 0;
      if (shuffle) shuffleArray(order);  
    }
    load();
    audio.play();
  });

  if (shuffle) shuffleArray(order);
  load();
  audio.play().catch(function () {       
    const resume = function () {
      audio.play();
      ["click", "touchstart", "scroll"].forEach(function (e) {
        document.removeEventListener(e, resume);
      });
    };
    ["click", "touchstart", "scroll"].forEach(function (e) {
      document.addEventListener(e, resume, { passive: true });
    });
  });
})();


